func TestPostgresWorkspaceDeletionUsesUserBotLifecycleLock(t *testing.T) {
	ctx := context.Background()
	st := newIsolatedPostgresTestStore(t)
	if err := st.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	owner, err := st.EnsureBootstrap(ctx, "Workspace Owner", "postgres-setup-workspace-delete-owner@example.com")
	if err != nil {
		t.Fatal(err)
	}
	workspaces, err := st.ListWorkspaces(ctx, owner.ID)
	if err != nil {
		t.Fatal(err)
	}
	workspace := workspaces[0]
	bot, _, err := st.CreateBot(ctx, store.CreateBotInput{
		WorkspaceID: workspace.ID,
		OwnerUserID: owner.ID,
		DisplayName: "Owned Setup Bot",
		Handle:      "postgres-owned-setup-delete-bot",
		CreatedBy:   owner.ID,
	})
	if err != nil {
		t.Fatal(err)
	}
	setup, err := st.CreateBotSetupCode(ctx, store.CreateBotSetupCodeInput{
		WorkspaceID: workspace.ID,
		BotUserID:   bot.ID,
		Name:        "workspace-delete",
		CreatedBy:   owner.ID,
	})
	if err != nil {
		t.Fatal(err)
	}

	blocker := mustBeginPostgresTx(t, ctx, st.db)
	if err := lockBotLifecycleTx(ctx, blocker, bot.ID); err != nil {
		t.Fatal(err)
	}

	deleteResult := make(chan error, 1)
	go func() {
		_, deleteErr := st.DeleteWorkspace(ctx, workspace.ID, owner.ID)
		deleteResult <- deleteErr
	}()
	waitForBlockedBotLifecycleOperations(t, ctx, st.db, 1)
	if err := blocker.Commit(); err != nil {
		t.Fatal(err)
	}

	select {
	case err := <-deleteResult:
		if err != nil {
			t.Fatalf("workspace deletion failed after lifecycle lock release: %v", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("workspace deletion did not resume after lifecycle lock release")
	}
	if _, err := st.ClaimBotSetupCode(ctx, setup.Code); !errors.Is(err, store.ErrSetupCodeInvalid) {
		t.Fatalf("workspace deletion left its user-owned bot setup code claimable: %v", err)
	}
}

func TestPostgresCreateBotWithoutInitialToken(t *testing.T) {
	dsn := os.Getenv("CLICKCLACK_POSTGRES_TEST_DSN")
	if dsn == "" {
		t.Skip("set CLICKCLACK_POSTGRES_TEST_DSN to run Postgres integration smoke")
	}
	ctx := context.Background()
	st, err := Open(dsn)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = st.Close() })
	if err := st.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	suffix := time.Now().UTC().Format("20060102150405.000000000")
	owner, err := st.CreateUser(ctx, store.CreateUserInput{DisplayName: "Skip Token Owner", Email: "pg-skip-owner-" + suffix + "@example.com"})
	if err != nil {
		t.Fatal(err)
	}
	workspace, err := st.CreateWorkspace(ctx, store.CreateWorkspaceInput{Name: "Skip Token " + suffix}, owner.ID)
	if err != nil {
		t.Fatal(err)
	}

	input := store.CreateBotInput{
		WorkspaceID:      workspace.ID,
		DisplayName:      "Codeless Bot",
		CreatedBy:        owner.ID,
		SetupNonce:       "0d4e8a1c-9f27-4f6e-8c35-1a2b3c4d5e6f",
		SkipInitialToken: true,
	}
	bot, token, err := st.CreateBot(ctx, input)
	if err != nil {
		t.Fatal(err)
	}
	if token.ID != "" || token.Token != "" {
		t.Fatalf("expected no initial token, got %#v", token)
	}
	replayed, replayedToken, err := st.CreateBot(ctx, input)
	if err != nil {
		t.Fatal(err)
	}
	if replayed.ID != bot.ID || replayedToken.ID != "" {
		t.Fatalf("expected tokenless replay to reuse bot, got %#v / %#v", replayed, replayedToken)
	}
	conflicting := input
	conflicting.DisplayName = "Different Bot"
	if _, _, err := st.CreateBot(ctx, conflicting); !errors.Is(err, store.ErrSetupNonceConflict) {
		t.Fatalf("expected changed tokenless replay to conflict, got %v", err)
	}
	conflicting = input
	conflicting.SkipInitialToken = false
	if _, _, err := st.CreateBot(ctx, conflicting); !errors.Is(err, store.ErrSetupNonceConflict) {
		t.Fatalf("expected token mode reuse of tokenless nonce to conflict, got %v", err)
	}
	if _, err := st.CreateBotToken(ctx, store.CreateBotTokenInput{
		WorkspaceID: workspace.ID,
		BotUserID:   bot.ID,
		Name:        "manual",
		Scopes:      []string{"messages:write"},
		SetupNonce:  input.SetupNonce,
		CreatedBy:   owner.ID,
	}); !errors.Is(err, store.ErrSetupNonceConflict) {
		t.Fatalf("expected token mint reuse of tokenless nonce to conflict, got %v", err)
	}
	tokens, err := st.ListBotTokensForWorkspace(ctx, workspace.ID, bot.ID, owner.ID)
	if err != nil {
		t.Fatal(err)
	}
	if len(tokens) != 0 {
		t.Fatalf("expected zero tokens for bot, got %d", len(tokens))
	}

	setup, err := st.CreateBotSetupCode(ctx, store.CreateBotSetupCodeInput{
		WorkspaceID: workspace.ID,
		BotUserID:   bot.ID,
		Name:        "gateway",
		Scopes:      []string{"messages:write"},
		CreatedBy:   owner.ID,
	})
	if err != nil {
		t.Fatal(err)
	}
	claim, err := st.ClaimBotSetupCode(ctx, setup.Code)
	if err != nil {
		t.Fatal(err)
	}
	if claim.Bot.ID != bot.ID {
		t.Fatalf("claim bot mismatch: %#v", claim.Bot)
	}
	tokens, err = st.ListBotTokensForWorkspace(ctx, workspace.ID, bot.ID, owner.ID)
	if err != nil {
		t.Fatal(err)
	}
	if len(tokens) != 1 {
		t.Fatalf("expected exactly one token after claim, got %d", len(tokens))
	}
}

package postgres

import (
	"context"
	"fmt"
	"sort"
	"sync"
	"testing"

	"github.com/openclaw/clickclack/apps/api/internal/store"
)

func TestGetThreadHydratesReactions(t *testing.T) {
	ctx := context.Background()
	st := newIsolatedPostgresTestStore(t)
	if err := st.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	owner, err := st.EnsureBootstrap(ctx, "Reaction Owner", "postgres-reaction-owner@example.com")
	if err != nil {
		t.Fatal(err)
	}
	workspaces, err := st.ListWorkspaces(ctx, owner.ID)
	if err != nil {
		t.Fatal(err)
	}
	member, err := st.CreateUser(ctx, store.CreateUserInput{DisplayName: "Reaction Member", Email: "postgres-reaction-member@example.com"})
	if err != nil {
		t.Fatal(err)
	}
	if err := st.AddWorkspaceMember(ctx, workspaces[0].ID, member.ID, store.WorkspaceRoleMember); err != nil {
		t.Fatal(err)
	}
	channels, err := st.ListChannels(ctx, workspaces[0].ID, owner.ID)
	if err != nil {
		t.Fatal(err)
	}
	root, _, err := st.CreateMessage(ctx, store.CreateMessageInput{ChannelID: channels[0].ID, AuthorID: owner.ID, Body: "root", Nonce: "reaction-root"})
	if err != nil {
		t.Fatal(err)
	}
	reply, _, _, err := st.CreateThreadReply(ctx, store.CreateThreadReplyInput{RootMessageID: root.ID, AuthorID: owner.ID, Body: "reply"})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := st.AddReaction(ctx, store.CreateReactionInput{MessageID: root.ID, UserID: owner.ID, Emoji: "👍"}); err != nil {
		t.Fatal(err)
	}
	if _, err := st.AddReaction(ctx, store.CreateReactionInput{MessageID: root.ID, UserID: member.ID, Emoji: "👍"}); err != nil {
		t.Fatal(err)
	}
	if _, err := st.AddReaction(ctx, store.CreateReactionInput{MessageID: root.ID, UserID: member.ID, Emoji: "👀"}); err != nil {
		t.Fatal(err)
	}
	if _, err := st.AddReaction(ctx, store.CreateReactionInput{MessageID: reply.ID, UserID: owner.ID, Emoji: "🔥"}); err != nil {
		t.Fatal(err)
	}

	threadResult1, err := st.GetThreadPage(ctx, root.ID, owner.ID, store.ThreadPageRequest{MessagePageRequest: store.MessagePageRequest{Limit: 10}})

	threadRoot, replies := threadResult1.Root, threadResult1.Replies
	if err != nil {
		t.Fatal(err)
	}
	if len(threadRoot.Reactions) != 2 {
		t.Fatalf("expected hydrated root reaction, got %#v", threadRoot.Reactions)
	}
	if got := reactionSummary(threadRoot.Reactions, "👍"); got.Count != 2 || !got.ReactedByMe {
		t.Fatalf("expected owner summary for thumbs-up, got %#v", got)
	}
	if got := reactionSummary(threadRoot.Reactions, "👀"); got.Count != 1 || got.ReactedByMe {
		t.Fatalf("expected owner summary for eyes, got %#v", got)
	}
	if len(replies) != 1 || len(replies[0].Reactions) != 1 || replies[0].Reactions[0].Emoji != "🔥" || !replies[0].Reactions[0].ReactedByMe {
		t.Fatalf("expected hydrated reply reaction, got %#v", replies)
	}
	byNonce, err := st.GetMessageByNonce(ctx, owner.ID, "reaction-root")
	if err != nil {
		t.Fatal(err)
	}
	if got := reactionSummary(byNonce.Reactions, "👍"); got.Count != 2 || !got.ReactedByMe {
		t.Fatalf("expected nonce lookup to hydrate reactions, got %#v", byNonce.Reactions)
	}

	concurrent, _, err := st.CreateMessage(ctx, store.CreateMessageInput{ChannelID: channels[0].ID, AuthorID: owner.ID, Body: "concurrent"})
	if err != nil {
		t.Fatal(err)
	}
	const writers = 8
	users := make([]store.User, 0, writers)
	users = append(users, owner, member)
	for index := len(users); index < writers; index++ {
		user, err := st.CreateUser(ctx, store.CreateUserInput{
			DisplayName: fmt.Sprintf("Reaction Writer %d", index),
			Email:       fmt.Sprintf("postgres-reaction-writer-%d@example.com", index),
		})
		if err != nil {
			t.Fatal(err)
		}
		if err := st.AddWorkspaceMember(ctx, workspaces[0].ID, user.ID, store.WorkspaceRoleMember); err != nil {
			t.Fatal(err)
		}
		users = append(users, user)
	}

	start := make(chan struct{})
	counts := make(chan int64, writers)
	errs := make(chan error, writers)
	var wg sync.WaitGroup
	for _, user := range users {
		wg.Add(1)
		go func(userID string) {
			defer wg.Done()
			<-start
			event, err := st.AddReaction(ctx, store.CreateReactionInput{
				MessageID: concurrent.ID,
				UserID:    userID,
				Emoji:     "⚡",
			})
			if err != nil {
				errs <- err
				return
			}
			payload, ok := event.Payload.(map[string]any)
			if !ok {
				errs <- fmt.Errorf("unexpected reaction payload %#v", event.Payload)
				return
			}
			count, ok := payload["count"].(int64)
			if !ok {
				errs <- fmt.Errorf("unexpected reaction count %#v", payload["count"])
				return
			}
			counts <- count
		}(user.ID)
	}
	close(start)
	wg.Wait()
	close(errs)
	close(counts)
	for err := range errs {
		t.Fatal(err)
	}
	gotCounts := make([]int, 0, writers)
	for count := range counts {
		gotCounts = append(gotCounts, int(count))
	}
	sort.Ints(gotCounts)
	for index, count := range gotCounts {
		if want := index + 1; count != want {
			t.Fatalf("expected serialized authoritative counts 1..%d, got %#v", writers, gotCounts)
		}
	}
}

func reactionSummary(reactions []store.ReactionSummary, emoji string) store.ReactionSummary {
	for _, reaction := range reactions {
		if reaction.Emoji == emoji {
			return reaction
		}
	}
	return store.ReactionSummary{}
}

package postgres

import (
	"context"
	"database/sql"
