	}

	c := apiClient{
		opts: clientOptions{Server: "http://clickclack.invalid"},
		http: &http.Client{Transport: roundTripperFunc(func(*http.Request) (*http.Response, error) {
			return nil, errors.New("network unavailable")
		})},
	}
	err := c.reactions([]string{"remove", "msg_1", "👍"})
	if err == nil || !strings.Contains(err.Error(), "network unavailable") {
		t.Fatalf("network error = %v", err)
	}
}

func captureStdout(t *testing.T, fn func() error) string {
	t.Helper()
	oldStdout := os.Stdout
	outputFile, err := os.CreateTemp(t.TempDir(), "stdout")
	if err != nil {
		t.Fatal(err)
	}
	os.Stdout = outputFile
	defer func() {
		os.Stdout = oldStdout
		_ = outputFile.Close()
	}()
	if err := fn(); err != nil {
		t.Fatal(err)
	}
	if _, err := outputFile.Seek(0, io.SeekStart); err != nil {
		t.Fatal(err)
	}
	output, err := io.ReadAll(outputFile)
	if err != nil {
		t.Fatal(err)
	}
	return string(output)
}

func TestCaptureStdoutHandlesLargeOutput(t *testing.T) {
	want := strings.Repeat("large output\n", 1<<16)
	got := captureStdout(t, func() error {
		_, err := io.WriteString(os.Stdout, want)
		return err
	})
	if got != want {
		t.Fatalf("captured %d bytes, want %d", len(got), len(want))
	}
}

type roundTripperFunc func(*http.Request) (*http.Response, error)

func (fn roundTripperFunc) RoundTrip(req *http.Request) (*http.Response, error) {
	return fn(req)
}

func pastTenseAction(action string) string {
	if action == "add" {
		return "added"
	}
	return "removed"
}

