	}, store.Event{ID: "evt_probe"}, []byte(`{"event":"probe"}`)); err == nil {
		t.Fatal("event callback reached a loopback target")
	}
	if got := requests.Load(); got != 0 {
		t.Fatalf("loopback callback server received %d requests", got)
	}
}

